// ✅ 이미 일어난 사실 (바뀌지 않는다)
{ type: 'ItemAdded',   id, text, by, at }
{ type: 'ItemRenamed', id, text, by, at }
{ type: 'ItemDeleted', id, by, at }

// ❌ 명령형 이름 (AddItem) 은 "요청" 이지 "사실" 이 아니다
// 이벤트는 절대 수정·삭제하지 않는다 — 취소도 새 이벤트로

function project(events) {
  const items = new Map();
  for (const e of events) {
    if (e.type === 'ItemAdded')   items.set(e.id, { id: e.id, text: e.text });
    if (e.type === 'ItemRenamed') items.get(e.id).text = e.text;
    if (e.type === 'ItemDeleted') items.delete(e.id);
  }
  return [...items.values()];
}

// 이벤트가 많아지면 스냅샷을 주기적으로 저장하고
// "스냅샷 + 그 이후 이벤트" 만 접는다
